class Widget {
  constructor(public size: number, public color: string) {}
  clone() { return new Widget(this.size, this.color); }
}
const original = new Widget(10, 'red');
const copy = original.clone();

class ReportTemplate {
  constructor(public title: string, public layout: object) {}
  clone() { return Object.assign(Object.create(Object.getPrototypeOf(this)), this); }
}
const base = new ReportTemplate('Monthly', { columns: 3 });
const derived = base.clone();

// Version A
const templatesA: { [k: string]: any } = {};
templatesA['invoice'] = { items: [], tax: 0 };
function createInvoiceA(name: string) {
  return templatesA[name]; // returns shared object
}

// Version B
const templatesB: { [k: string]: any } = {};
templatesB['invoice'] = { items: [], tax: 0 };
function createInvoiceB(name: string) {
  const proto = templatesB[name];
  return { ...proto, items: proto.items.slice() }; // returns independent clone
}
